<script setup lang="ts">
import { computed, ref } from 'vue'
const props=defineProps<{title:string;times:string[];series:Array<{name:string;color:string;values:Array<number|null>}>;unit?:string;max?:number;gapSeconds?:number}>()
const hover=ref(-1),width=720,height=190,left=52,right=18,top=18,bottom=30
const hasValues=computed(()=>props.times.length>0&&props.series.some(s=>s.values.some(v=>v!=null&&Number.isFinite(v))))
const maximum=computed(()=>props.max||Math.max(1,...props.series.flatMap(s=>s.values.filter((v):v is number=>v!=null&&Number.isFinite(v))))*1.12)
const x=(i:number)=>left+i/Math.max(props.times.length-1,1)*(width-left-right)
const y=(v:number)=>top+(1-v/maximum.value)*(height-top-bottom)
const paths=computed(()=>props.series.map(s=>{let text='',connected=false;for(let i=0;i<s.values.length;i++){const value=s.values[i];const gap=i>0&&props.gapSeconds&&(new Date(props.times[i]!).getTime()-new Date(props.times[i-1]!).getTime())>props.gapSeconds*1000;if(value==null||!Number.isFinite(value)){connected=false;continue};text+=`${connected&&!gap?'L':'M'}${x(i).toFixed(1)},${y(value).toFixed(1)} `;connected=true};return text}))
function move(event:MouseEvent){const rect=(event.currentTarget as SVGElement).getBoundingClientRect();const position=(event.clientX-rect.left)/rect.width*width;hover.value=Math.max(0,Math.min(props.times.length-1,Math.round((position-left)/(width-left-right)*Math.max(props.times.length-1,1))))}
const fmt=(v:number)=>v>=1000?(v/1000).toFixed(1)+'k':v.toFixed(v<10?1:0)
const time=(s:string)=>new Date(s).toLocaleString('zh-CN',{hour12:false})
</script>
<template><section class="metric-panel"><div class="chart-head"><strong>{{title}}</strong><div><span v-for="s in series" :key="s.name"><i :style="{background:s.color}"></i>{{s.name}}</span><span>{{unit}}</span></div></div><div class="plot"><svg v-if="hasValues" :viewBox="`0 0 ${width} ${height}`" @mousemove="move" @mouseleave="hover=-1" role="img" :aria-label="title"><g v-for="n in [0,1,2,3,4]" :key="n"><line :x1="left" :x2="width-right" :y1="y(maximum*n/4)" :y2="y(maximum*n/4)" stroke="#e7edf5"/><text :x="left-9" :y="y(maximum*n/4)+4" text-anchor="end" fill="#8090a4" font-size="10">{{fmt(maximum*n/4)}}</text></g><path v-for="(s,index) in series" :key="s.name" :d="paths[index]" :stroke="s.color" fill="none" stroke-width="1.8"/><circle v-for="(s,index) in series" v-show="times.length===1 && s.values[0]!=null" :key="`point-${index}`" :cx="x(0)" :cy="y(s.values[0]||0)" r="3" :fill="s.color"/><line v-if="hover>=0" :x1="x(hover)" :x2="x(hover)" :y1="top" :y2="height-bottom" stroke="#93a4ba" stroke-dasharray="3 3"/><text :x="left" :y="height-7" fill="#8090a4" font-size="10">{{new Date(times[0]!).toLocaleTimeString('zh-CN')}}</text><text :x="width-right" :y="height-7" text-anchor="end" fill="#8090a4" font-size="10">{{new Date(times[times.length-1]!).toLocaleTimeString('zh-CN')}}</text></svg><el-empty v-else description="暂无趋势数据" :image-size="45"/><div v-if="hover >= 0 && times[hover]" class="tooltip"><div>{{time(times[hover]!)}}</div><div v-for="s in series" :key="s.name">{{s.name}}：{{s.values[hover]==null?'无数据':fmt(s.values[hover]!)}} {{unit}}</div></div></div></section></template>
<style scoped>.metric-panel{background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:16px;min-width:0}.chart-head{display:flex;justify-content:space-between;align-items:center;gap:8px;color:#34465d;font-size:13px}.chart-head strong{font-weight:600}.chart-head>div{display:flex;gap:12px;font-size:11px;color:#718198}.chart-head i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:5px}.plot{position:relative;min-height:175px}.plot svg{width:100%;display:block}.tooltip{position:absolute;right:12px;top:15px;background:rgba(22,36,58,.92);color:#fff;padding:9px 12px;border-radius:5px;font-size:11px;line-height:1.8;pointer-events:none}</style>
